@spec tm_fx_region_spec  src=tests/specs/tm_fx_region_spec.lua  loc=2202  sha=0d33378  cases=79
@exercises dataStore (h.ds), midiManager (h.fm), trackerManager (h.tm), generators (generators), trackerView (h.vm)
@surface   ds:get, fm:dump, ds:assign, tm:rebuild, tm:getChannel, tm:addEvent, tm:flush, tm:assignParked, tm:deleteParked, tm:addParked, tm:subscribe, ds:subscribe, ds:unsubscribe, generators.retarget, vm:addFxStage, vm:noteFx, vm:removeFxStage, tm:freezeRegion, tm:byUuid
@harness   mk

# Intent
  Note macros v2: region hosts. The N=0 sine pb seat stream proves the generator-side substrate
  (ds, 4.6 producer split, reconcile, G4 round-trip). see design/note-macros-v2.md

# Helpers
  @fn centsToRaw(cents, pbRange)  @ 11-13
  @fn rawToCents(raw, pbRange)  @ 15-17
  @fn inPbWindow(h, chan, ppq)  @ 21-26
      -- A seat is recognized purely by region membership: any pb inside a live region's span (bounds
      -- inclusive of endppq, so the terminal re-centre seat counts). see design/note-macros-v2.md § Route-by-window
  @fn authoredPb(h, chan, ppq)  @ 30-34
      -- An authored pb on the wire: one no live pb window covers (a covered pb is a seat). `val` is raw
      -- (centsToRaw of wire-cents + detune); `cents` the persisted intent. nil while a window parks it off.
  @fn derivedPbs(h, chan)  @ 38-44
      -- The seated curve of a pb-replace region, hidden from columns. Seats are markerless -- there is no
      -- marker to filter on; the live window IS their identity. Recognized purely by region membership.
  @fn derivedPb(h, chan, ppq)  @ 46-48
  @fn stashOfType(h, evType)  @ 51-57
      -- The cc / pb slice of the unified fxParked off-take stash.
  @fn inCcSpan(h, chan, ppq)  @ 61-66
      -- Half-open region membership on a channel (matches production's covered()): a cc-replace seat lives
      -- in [startppq, endppq). see design/note-macros-v2.md § Route-by-window
  @fn fillRecords(h, chan, cc)  @ 70-78
      -- The seated replace curve on a cc target, hidden from columns. Seats are markerless -- the live region
      -- span IS their identity; the authored cc it covers is parked off-take.
  @fn fillsOf(h, chan, cc)  @ 79-86
  @fn ccFillAt(h, chan, cc, ppq)  @ 87-89
  @fn authoredCC(h, chan, cc, ppq)  @ 93-98
      -- A non-derived authored cc on the take, outside any live cc-replace window (an in-window cc is a
      -- markerless seat, not authored); nil once a window parks the authored cc off.
  @fn injectRegion(h, over)  @ 101-106
      -- A region is channel x ppq span + fx; no host note. Inject via ds, then rebuild.
  @fn anyNoteOnChan(h, chan)  @ 108-113
  @fn addNote(h, over)  @ 119-124
  @fn injectArp(h, over)  @ 126-131
  @fn derivedNotes(h)  @ 135-147
      -- Derived notes the region produced -- routed out of columns, tagged with the region
      -- uuid. Sorted by onset then lane; identity swing, so ppq == the logical step time.
  @fn field(ns, k)  @ 149
  @fn columnPitches(h, chan)  @ 153-162
      -- The note pitches standing in a channel's note columns -- what the grid shows, as against
      -- fm:dump()'s wire content. Note columns also carry re-projected pa cells, so filter on evType.
  @fn authoredPitches(h)  @ 166-173
      -- Authored (non-derived) note pitches still sounding in the take, sorted. Empty when a
      -- replace region has parked the whole chord off-take.

# Cases
  @case 'fx region (N=0): sine over a span seats a free-LFO pb stream with no host note'  [harness]  @ 180-190
  @case 'fx region: pb seats re-centre the channel at the region window end'  [harness]  @ 196-205
  @case 'G4: region pb seat stream is byte-identical across rebuild -> flush'  [harness]  @ 211-225
  @case 'G2: removing the region leaves no pb seat after reconcile'  [harness]  @ 231-245
  @case 'replace: arp over a held triad packs into lane 1; the chord parks off the take'  [harness]  @ 251-263
  @case 'replace: a PA under the parked host parks off-take with it, restores on unpark'  [harness]  @ 269-303
  @case 'two rebuilds over an arp region allocate byte-identical derived notes + lanes'  [harness]  @ 309-321
  @case 'replace: arp samples the playing notes continuously, with no collision nudge'  [harness]  @ 325-336
  @case 'replace: a parked member tail is realised against its same-lane successor'  [harness]  @ 340-348
  @case 'chain [arp, velPattern]: the pattern accents the arp steps'  [harness]  @ 354-365
  @case 'chain [velPattern, arp]: the chord takes the pattern first, the arp reads the folded stream'  [harness]  @ 369-381
  @case 'velPattern alone owns the note stream: the chord parks and re-emits re-velocitied'  [harness]  @ 385-395
  @case 'replace: a parked member tail is clipped by an on-take note after the region'  [harness]  @ 399-412
  @case 'replace: a parked member tail is clipped by a parked note in a later region'  [harness]  @ 416-433
  @case 'replace husk (no kinds) parks nothing -- its members keep sounding'  [harness]  @ 437-443
  @case 'replace: removing the region restores the parked chord to the take'  [harness]  @ 447-462
  @case 'G4: replace arp + parked chord are byte-identical across rebuild -> flush'  [harness]  @ 466-478
  @case 'park identity (note): render cell carries chan+uuid; the fxParked stash is logical-only'  [harness]  @ 484-497
  @case 'park round-trip carries arbitrary authored metadata, not just whitelisted fields'  [harness]  @ 501-513
  @case 'park identity (cc): render cell carries chan+ppq; the fxParkedCC stash is logical-only'  [harness]  @ 517-537
  @case 'assignParked (note): edit a parked pitch -> stash updated, still parked, renders the new pitch'  [harness]  @ 543-554
  @case 'deleteParked (note): a parked note leaves the stash and is not restored while still covered'  [harness]  @ 558-567
  @case 'addParked (note): typing into a replace window stashes a logical spec (minted uuid), off the take'  [harness]  @ 571-591
  @case 'parked cc: assignParked then deleteParked edits the off-take cc stash symmetrically'  [harness]  @ 595-617
  @case 'parked pb sharing a ppq with a parked note edits and deletes independently of it'  [harness]  @ 623-647
  @case 'parked PAs sharing a ppq across lanes are addressed by pitch, not by onset alone'  [harness]  @ 654-684
  @case 'shrinking a cc-replace window restores the authored cc value, not the fill it sat under'  [harness]  @ 690-730
  @case 'one flush, one rebuild: a parked edit + a normal note land together (the multi-select guard)'  [harness]  @ 734-748
  @case 'parked-only flush drives exactly one rebuild (no mm round-trip)'  [harness]  @ 752-764
  @case 'fxParked dataChanged (undo rewind) rebuilds the grid'  [harness]  @ 768-777
  @case 'an error escaping the parked flush leaves later ds changes still rebuilding'  [harness]  @ 781-796
  @case 'augment by kind: a continuous (sine) region leaves its covered notes sounding'  [harness]  @ 802-809
  @case 'arp over a span with no sounding notes emits nothing'  [harness]  @ 815-820
  @case 'fx region: the producer hands the generator notes/pas/ccs/ats input streams'  [harness]  @ 826-856
  @case 'fx region: an OPEN member clips to the next same-lane onset, not the window end'  [harness]  @ 860-883
  @case 'fx region: host.pb carries authored pb breakpoints, excluding absorber fakes'  [harness]  @ 887-911
  @case 'fx region: pb replace seats the absolute curve on the base lane, no carrier'  [harness]  @ 917-950
  @case 'fx region: pb replace with no authored base seats the curve verbatim'  [harness]  @ 954-973
  @case 'fx chain (continuous): [replace, augment] -- the augment stage wobbles the replaced curve'  [harness]  @ 979-1007
  @case 'fx chain (continuous): [augment, replace] -- the replace stage overwrites the folded stream'  [harness]  @ 1011-1037
  @case 'fx region (pb): two overlapping replace regions -- later storage wins pointwise, not summed'  [harness]  @ 1043-1069
  @case 'fx region (pb): a later replace region wipes an earlier augment (storage = precedence)'  [harness]  @ 1073-1101
  @case 'fx region (pb): overlapping replace regions with differing windows -- each owns its exclusive tail'  [harness]  @ 1105-1135
  @case 'fx region (cc): two overlapping replace regions -- later storage wins, not the additive fold'  [harness]  @ 1139-1165
  @case 'fx region (cc augment): overlapping differing windows -- each augment folds only in its own window'  [harness]  @ 1169-1200
  @case 'fx region (pb): differing-window overlap seats are byte-stable across a no-change rebuild'  [harness]  @ 1204-1249
  @case 'fx region: pb replace rides the curve over the detune -- I1 holds'  [harness]  @ 1253-1278
  @case 'fx region: removing a pb replace region restores the authored wire'  [harness]  @ 1282-1307
  @case 'fx region: pb replace densifies a curved segment split by a detune onset'  [harness]  @ 1311-1344
  @case 'fx region: a dense pb replace curve seats markerless -- no uuid, no metadata sidecar'  [harness]  @ 1350-1377
  @case 'fx region: removing a pb replace region sweeps its seats, leaving only the restored authored pb'  [harness]  @ 1381-1413
  @case 'fx region (cc replace): the generated curve lands on the target cc lane; no carrier'  [harness]  @ 1419-1445
  @case 'fx region (cc replace): removing the region restores the parked cc and drops the fill'  [harness]  @ 1449-1475
  @case 'G4 (cc replace): the fill is byte-identical and re-adds nothing across a no-change rebuild'  [harness]  @ 1479-1505
  @case 'cc replace: a dense fill curve seats markerlessly (no uuid, no eventMeta)'  [harness]  @ 1509-1529
  @case 'fx region (cc augment): un-automated target seats base(rest) + macro, markerless, off columns'  [harness]  @ 1535-1557
  @case 'fx region (cc augment): over authored automation the seat is authored-base + macro'  [harness]  @ 1561-1581
  @case 'fx region (cc augment): two overlapping regions sum every stream (N-stream regression guard)'  [harness]  @ 1585-1613
  @case 'fx region (cc augment): region.fx.rest overrides the default resting base'  [harness]  @ 1617-1635
  @case 'fx region (cc): retargeting a stage restores the old controller and parks the new one'  [harness]  @ 1641-1669
  @case 'note-host augment (cc): a sounding note drives summed seats like a degenerate region'  [harness]  @ 1673-1702
  @case 'replace: a preceding on-take tail clips at the parked chord onset, not past it'  [harness]  @ 1708-1724
  @case 'replace: a derived tile is not truncated by a parked member it replaced'  [harness]  @ 1728-1744
  @case 'deleting a self-parked [trill, sine] host leaves no orphaned pb seats'  [harness]  @ 1750-1775
  @case 'removing the note kind from a self-parked [sine, trill] host keeps its authored cc parked'  [harness]  @ 1781-1830
  @case 'a same-pass note park widens a surviving host window and parks the exposed authored cc'  [harness]  @ 1837-1865
  @case 'freeze: the derived chord is promoted to authored, and region + stash go with it'  [harness]  @ 1871-1890
  @case 'freeze: the standing reconcile does not restore the destroyed members'  [harness]  @ 1894-1906
  @case 'freeze: the seated pb curve stands as authored automation'  [harness]  @ 1910-1944
  @case 'freeze: a promoted note keeps the tail the walk clipped for it'  [harness]  @ 1948-1974
  @case 'freeze: the whole projection rides one flush and one rebuild'  [harness]  @ 1978-1987
  @case 'freeze (mixed chain): the arp is authored and the cc seats keep their column'  [harness]  @ 1991-2013
  @case 'freeze (parked host): the trill output is authored and the host leaves the stash'  [harness]  @ 2019-2056
  @case 'freeze (on-take host): the cc curve is authored and the host keeps its note'  [harness]  @ 2060-2086
  @case 'freeze (host parked by a region): the chain goes, the note stays parked'  [harness]  @ 2092-2111
  @case 'freeze declines on a plain note and changes nothing'  [harness]  @ 2115-2124
  @case 'park windows: a self-parking note host contributes one window, not two'  [harness]  @ 2132-2148
  @case 'park windows: a self-parking note host runs its chain once, not twice'  [harness]  @ 2154-2171
  @case 'freeze (identical-window neighbour): the survivor keeps its window and its curve'  [harness]  @ 2177-2199

